    def _info_decision(question: str, *_args, **_kwargs):
        if "длится" in question:
            return DemoSalonDecision(
                action="reply",
                response="DURATION",
                intent="duration_query",
                meta={"service_query": "маникюр"},
            )
        return DemoSalonDecision(
            action="reply",
            response="PRICE",
            intent="price_query",
            meta={"service_query": "маникюр"},
        )

    policy_handler = {"policy_type": "demo_salon", "truth_gate": _truth_gate}

